INSERT INTO main.email_template (created_at, updated_at, name, body) VALUES(now(), now(), 'activate_commerce', '<!DOCTYPE html> <html lang="es" xmlns="https://www.w3.org/1999/xhtml"> <head> <meta charset="UTF-8"> <meta name="viewport" content="width=device-width,initial-scale=1"> <meta name="x-apple-disable-message-reformatting"> <title>Facturación Electrónica - Activación de Comercio</title> </head> <body> <table style="width:100%; height:auto; border-collapse:collapse; border:0; border-spacing:0; background:#ffffff; font-family: Roboto, sans-serif;"> <tbody> <tr> <td align="center" style="margin:0; padding:0; font-family:Roboto, sans-serif;"> <table style="background-color:#f5f8fb; margin:0; padding:0; width:500px; max-width:500px; border-collapse:collapse; border-spacing:0;"> <tbody> <tr> <td style="margin:0; display:block; margin:0 12px; padding:20px; background-color:#004aad; border-radius:16px; max-width:480px; width:480px;"> <h2 style="color:#ffffff; font-size:18px; margin:0; text-align:center;">Facturación Electrónica</h2> </td> </tr> <tr> <td style="padding:20px 12px; background:#f5f8fb;"> <table style="width:100%; border-collapse:collapse; border:0; border-spacing:0; text-align:left;"> <tbody> <tr> <td style="background:#ffffff; border-radius:16px; padding:30px;"> <table width="100%" cellpadding="0" cellspacing="0"> <tr> <td> <h1 style="width:100%; font-weight:700; font-size:20px; margin:0 0 20px 0; color:#004aad; font-family:Roboto, sans-serif;"> ¡Hola, name_commerce! </h1> <p style="margin:0 0 20px 0; font-size:14px; line-height:24px; color:#555;"> Este correo ha sido enviado para verificar tu dirección de correo electrónico y activar tu comercio en nuestra plataforma. </p> </td> </tr> <tr> <td align="center" bgcolor="#004aad" style="border-radius:8px; padding:12px 24px; cursor:pointer;"> <a href="[domain]/auth" target="_blank" style="display:inline-block; color:#ffffff; text-decoration:none; font-weight:bold; font-size:14px; font-family:Roboto, sans-serif;"> Activar Comercio </a> </td> </tr> </table> </td> </tr> <tr><td style="height:5px;"></td></tr> <tr> <td style="background:none; border-radius:16px; padding:10px 20px; text-align:center;"> <p style="color:#8a869f; font-size:12px;"> &copy; 2025 <span style="color:#004aad; font-weight:bold;">Facturación Electrónica</span> - Todos los derechos reservados </p> <p style="color:#8a869f; font-size:12px;"> Por favor no responder a este correo directamente, ya que esta casilla no es revisada. </p> </td> </tr> <tr><td style="height:20px;"></td></tr> </tbody> </table> </td> </tr> </tbody> </table> </td> </tr> </tbody> </table> </body> </html>');